const PER_PAGE = 10
const PAGE_SIZES = [10, 25, 50, 100]
/** Exporting: records asked for at a time, and at most. */
const EXPORT_PAGE = 100
const EXPORT_MAX = 10_000

const features = tableFeatures({ columnVisibilityFeature, rowSelectionFeature })
const helper = createColumnHelper<typeof features, Rec>()

/** The list's state, in the URL. */
export interface ListSearch {
  page?: number
  cursor?: string
  q?: string
  sort?: string
  [filter: string]: string | number | undefined
}

/** Validates the list's URL: for the route's validateSearch. */
export function listSearch(search: Record<string, unknown>): ListSearch {
  const out: ListSearch = {}
  for (const [k, v] of Object.entries(search)) {
    if (k === "page") out.page = Number(v) > 0 ? Number(v) : undefined
    else if (typeof v === "string" || typeof v === "number") out[k] = v
  }
  return out
}

type Density = "comfortable" | "compact"
const densityKey = "esquadro:density"

/** How tight the lists' rows are: a preference of this browser. */
function useDensity(): [Density, (d: Density) => void] {
  const [density, set] = useState<Density>(() => {
    try {
      return localStorage.getItem(densityKey) === "compact" ? "compact" : "comfortable"
    } catch {
      return "comfortable"
    }
  })
  return [
    density,
    (d: Density) => {
      set(d)
      try {
        localStorage.setItem(densityKey, d)
      } catch {
        // Storage refused: the choice lasts the visit.
      }
    },
  ]
}

/** The pages to offer: the first, the last, and those around the current; 0 is a gap. */
export function pageNumbers(current: number, total: number): number[] {
  const out: number[] = []
  for (let n = 1; n <= total; n++) {
    if (n === 1 || n === total || Math.abs(n - current) <= 1) out.push(n)
    else if (out[out.length - 1] !== 0) out.push(0)
  }
  return out
}

/** Runs an action on each record, in turn; how many went through and failed. */
async function each(records: Rec[], run: (r: Rec) => Promise<unknown> | unknown) {
  let done = 0
  let failed = 0
  let error: unknown
  for (const r of records) {
    try {
      await run(r)
      done++
    } catch (e) {
      failed++
      error = e
    }
  }
  return { done, failed, error }
}

/**
 * A resource's list: its page, with its state in the URL; or, with a scope,
 * the records related to one (a category's products), on that record's
 * page, with its state in the page.
 */
export function ResourceList(props: { resource: Resource; description?: string; scope?: { param: string; value: string; label?: string } }) {
  const search = useSearch({ strict: false }) as ListSearch
  // A resource with a trash shows it at ?trash=1.
  if (props.resource.meta.trash && !props.scope && search.trash) return <TrashList resource={props.resource} />
  if (props.resource.queue && !props.scope) return <WithQueue {...props} />
  return <RecordsList {...props} />
}

type View = "table" | "queue"

/** The view of a resource with a queue, remembered by the browser. */
function useView(name: string): [View, (v: View) => void] {
  const key = `esquadro.view.${name}`
  const [view, setView] = useState<View>(() => {
    try {
      return localStorage.getItem(key) === "queue" ? "queue" : "table"
    } catch {
      return "table"
    }
  })
  const choose = (v: View) => {
    setView(v)
    try {
      localStorage.setItem(key, v)
    } catch {
      // Not remembered: the table again next time.
    }
  }
  return [view, choose]
}

/** A resource's list with its queue beside it, a tab each. */
function WithQueue(props: { resource: Resource; description?: string }) {
  const { meta, queue } = props.resource
  const [view, setView] = useView(meta.name)
  const pending = useQueue(props.resource)
  const count = pending.data?.total ?? pending.data?.items.length
  return (
    <Tabs value={view} onValueChange={(v) => setView(v as View)} className="flex flex-col gap-4">
      <TabsList className="self-start">
        <TabsTrigger value="table">
          <Rows3 /> {t("queueTable")}
        </TabsTrigger>
        <TabsTrigger value="queue">
          <ListChecks /> {queue?.label ?? t("queue")}
          {Boolean(count) && <span className="rounded-full bg-muted px-1.5 text-xs font-semibold tabular-nums">{count}</span>}
        </TabsTrigger>
      </TabsList>
      <TabsContent value="table">
        <RecordsList {...props} />
      </TabsContent>
      <TabsContent value="queue" className="flex flex-col gap-4 rounded-xl border border-border bg-card p-5">
        <PageHeader title={meta.label} description={props.description} />
        <QueueView resource={props.resource} />
      </TabsContent>
    </Tabs>
  )
}

function RecordsList({
  resource,
  description,
  scope,
}: {
  resource: Resource
  description?: string
  scope?: { param: string; value: string; label?: string }
}) {
  const { meta } = resource
  const embedded = scope !== undefined
  const tabsField = resource.table.tabs?.name === scope?.param ? undefined : resource.table.tabs
  const urlSearch = useSearch({ strict: false }) as ListSearch
  const [localSearch, setLocalSearch] = useState<ListSearch>({})
  const search = embedded ? localSearch : urlSearch
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const paged = meta.pagination.includes("page")
  const query: Record<string, unknown> = { ...search, ...(scope && { [scope.param]: scope.value }) }
  if (paged) {
    query.page = search.page ?? 1
    query.per_page = Number(search.per) || PER_PAGE
    delete query.per
  } else {
    query.limit = Number(search.per) || PER_PAGE
    delete query.per
  }
  const list = useQuery({
    queryKey: [meta.name, "list", query],
    queryFn: ({ signal }) => meta.api(api as never).list(query, { signal }),
    placeholderData: keepPreviousData,
  })
  // How many records each tab keeps, with the rest of the search: a page
  // of one, for its total (none by cursor).
  const tabValues: (string | undefined)[] = tabsField ? [undefined, ...(tabsField.values ?? ["true", "false"])] : []
  const counts = useQueries({
    queries: tabValues.map((v) => {
      const q: Record<string, unknown> = { ...query, page: 1, per_page: 1 }
      if (tabsField) q[tabsField.name] = v
      return {
        queryKey: [meta.name, "count", q],
        queryFn: ({ signal }) => meta.api(api as never).list(q, { signal }) as Promise<{ total?: number }>,
        enabled: paged,
        staleTime: 30_000,
        placeholderData: keepPreviousData,
      }
    }),
  })
  // A change of the list's state goes to the URL; typing replaces the entry
  // instead of filling the history.
  const set = (changes: Partial<ListSearch>, replace = false) =>
    embedded
      ? setLocalSearch((s) => Object.fromEntries(Object.entries({ ...s, ...changes }).filter(([, v]) => v !== undefined)))
      : navigate({ to: ".", search: (s: Record<string, unknown>) => ({ ...s, ...changes }) as never, replace })
  // A scoped list's own key is not a filter, nor a column.
  // The tabs' field is filtered by its tabs, not twice.
  const filters = (resource.table.filters ?? []).filter((f) => f.name !== scope?.param && f.name !== tabsField?.name)
  const tableColumns = resource.table.columns.filter((c) => columnField(c).name !== scope?.param)
  // The search counts only where the list has one.
  const filtering =
    (resource.table.search !== false && meta.sorts.includes("relevance") && Boolean(search.q)) ||
    [...filters, ...(tabsField ? [tabsField] : [])].some((f) => isActive(f, search as never))
  const clearAll = () =>
    set({ q: undefined, page: undefined, cursor: undefined, ...cleared(tabsField ? [...filters, tabsField] : filters) })

  // A refresh that fails keeps the last page loaded, under an alert, as
  // TanStack Query drops it when the new query errs.
  const last = useRef(list.data)
  if (list.data) last.current = list.data
  const page = list.data ?? (list.isError ? last.current : undefined)
  const items = useMemo(() => page?.items ?? [], [page])
  const canCreate = page?.can.includes("create") ?? false
  const duplicate = useDuplicate(meta)
  const actions = resource.actions ?? []
  const bulkActions = actions.filter(bulk)
  const canDeleteAny = items.some((r) => (r.can ?? []).includes("delete"))
  const selectable = resource.table.select !== false && (bulkActions.length > 0 || canDeleteAny)

  const [rowSelection, setRowSelection] = useState({})
  const [importing, setImporting] = useState(false)
  const [columnVisibility, setColumnVisibility] = useState<ColumnVisibilityState>(() =>
    Object.fromEntries(tableColumns.filter((c) => columnOptions(c).hidden).map((c) => [columnField(c).name, false])),
  )
  // Another page, filter or sorting: nothing selected.
  useEffect(() => setRowSelection({}), [JSON.stringify(search)])

  const remove = (r: Rec) => meta.api(api as never).delete(r.id, { ifMatch: r })
  const trashCount = useTrashCount(meta, !embedded)
  const { perform, dialog: actionDialog } = useActions(resource)
  const runOne = (a: Action, r: Rec) => perform(a, r)

  // What a record is called, in bold and with its picture: the resource's title, or its first column.
  const titleColumn = resource.title?.name ?? (tableColumns[0] && columnField(tableColumns[0]).name)
  const columns = useMemo(() => {
    const out = []
    if (selectable) {
      out.push(
        helper.display({
          id: "select",
          header: ({ table }) => (
            <Checkbox
              checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
              onCheckedChange={(v) => table.toggleAllPageRowsSelected(!!v)}
              aria-label={t("selectAll")}
            />
          ),
          cell: ({ row }) => (
            <Checkbox
              checked={row.getIsSelected()}
              onCheckedChange={(v) => row.toggleSelected(!!v)}
              onClick={(e) => e.stopPropagation()}
              aria-label={t("selectRow")}
            />
          ),
          enableHiding: false,
        }),
      )
    }
    for (const c of tableColumns) {
      const f = columnField(c)
      const o = columnOptions(c)
      const label = o.label ?? f.label
      out.push(
        helper.accessor((r: Rec) => r[f.name], {
          id: f.name,
          meta: { label },
          header: () => {
            const Icon = search.sort === f.name ? ArrowUp : search.sort === `-${f.name}` ? ArrowDown : ArrowUpDown
            const title = meta.sorts.includes(f.name) ? (
              <Button
                variant="ghost"
                size="sm"
                className="-ml-3 h-8 text-xs font-semibold tracking-wider text-muted-foreground uppercase hover:text-foreground"
                onClick={() => set({ sort: search.sort === f.name ? `-${f.name}` : f.name, cursor: undefined })}
              >
                {label}
                <Icon className="text-muted-foreground" />
              </Button>
            ) : (
              label
            )
            // A funnel by the column's name, when the list filters by it.
            const filter = resource.table.columnFilters ? filters.find((x) => x.name === f.name) : undefined
            if (!filter) return title
            return (
              <span className="inline-flex items-center gap-1">
                {title}
                <ColumnFilter field={filter} values={search as Record<string, string | undefined>} onChange={(c) => set({ ...c, page: undefined, cursor: undefined })} />
              </span>
            )
          },
          cell: ({ row }) => {
            const value = o.cell ? o.cell(row.original) : o.editable ? (
              <EditableCell meta={meta} field={f} record={row.original} />
            ) : (
              <FieldValue field={f} record={row.original} inline />
            )
            if (f.name !== titleColumn) return value
            // The column a record is called by carries its picture.
            // And, under the name, the resource's subtitle.
            const sub = resource.subtitle
            return (
              <div className="flex items-center gap-3">
                <Picture src={imageOf(resource, row.original)} name={String(row.original[f.name] ?? "")} />
                <div className="flex min-w-0 flex-col">
                  {value}
                  {sub && (
                    <span className="truncate text-xs font-medium text-muted-foreground">
                      {typeof sub === "function" ? sub(row.original) : <FieldValue field={sub} record={row.original} inline />}
                    </span>
                  )}
                </div>
              </div>
            )
          },
        }),
      )
    }
    out.push(
      helper.display({
        id: "actions",
        header: () => <span className="sr-only">{t("actions")}</span>,
        cell: ({ row }) => {
          const r = row.original
          const can = r.can ?? []
          const own = actions.filter((a) => allowed(a, r))
          return (
            <div className="flex justify-end gap-0.5 text-muted-foreground" onClick={(e) => e.stopPropagation()}>
              {can.includes("update") && (
                <Button variant="ghost" size="icon-sm" asChild aria-label={t("edit")}>
                  <Link to={`/${meta.name}/${r.id}/edit` as never}>
                    <Pencil />
                  </Link>
                </Button>
              )}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon-sm" className="data-[state=open]:bg-muted" aria-label={t("openMenu")}>
                    <MoreHorizontal />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-44">
                  <DropdownMenuItem asChild>
                    <Link to={`/${meta.name}/${r.id}` as never}>
                      <Eye /> {t("view")}
                    </Link>
                  </DropdownMenuItem>
                  {can.includes("update") && (
                    <DropdownMenuItem asChild>
                      <Link to={`/${meta.name}/${r.id}/edit` as never}>
                        <Pencil /> {t("edit")}
                      </Link>
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuItem onClick={() => copy(r.id)}>
                    <Hash /> {t("copyId")}
                  </DropdownMenuItem>
                  {canCreate && (
                    <DropdownMenuItem onClick={() => duplicate(r)}>
                      <Copy /> {t("duplicate")}
                    </DropdownMenuItem>
                  )}
                  {own.length > 0 && <DropdownMenuSeparator />}
                  {own.map((a) => (
                    <DropdownMenuItem key={a.label} variant={a.destructive ? "destructive" : "default"} onClick={() => runOne(a, r)}>
                      {a.icon && <a.icon />} {a.label}
                    </DropdownMenuItem>
                  ))}
                  {can.includes("delete") && (
                    <>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        variant="destructive"
                        onClick={async () => {
                          if (!(await confirmRemove(meta))) return
                          try {
                            await remove(r)
                            removed(meta, r, queryClient)
                          } catch (e) {
                            toast(describe(e), "error")
                          }
                          queryClient.invalidateQueries({ queryKey: [meta.name] })
                        }}
                      >
                        <Trash2 /> {t("delete")}
                      </DropdownMenuItem>
                    </>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          )
        },
        enableHiding: false,
      }),
    )
    return helper.columns(out)
  }, [resource, selectable, search, meta, actions, scope?.param, canCreate, titleColumn])

  const table = useTable({
    features,
    data: items,
    columns,
    state: { rowSelection, columnVisibility },
    getRowId: (r) => r.id,
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onColumnVisibilityChange: setColumnVisibility,
  })

  const selected = items.filter((r) => (rowSelection as Record<string, boolean>)[r.id])
  const runBulk = async (label: string, records: Rec[], run: (r: Rec) => Promise<unknown> | unknown, question?: string, destructive?: boolean) => {
    if (question && !(await ask(question, { destructive, description: destructive ? t("cantUndo") : undefined }))) return
    const { done, failed, error } = await each(records, run)
    if (failed === 0) toast(t("bulkDone", { done, label }))
    else toast(t("bulkFailed", { done, failed, error: describe(error) }), "error")
    setRowSelection({})
    queryClient.invalidateQueries({ queryKey: [meta.name] })
  }

  // The columns shown, as the file's columns.
  const shown = () =>
    table
      .getVisibleLeafColumns()
      .map((c) => tableColumns.find((tc) => columnField(tc).name === c.id))
      .filter((c) => c !== undefined)
      .map((c) => ({ field: columnField(c), label: columnOptions(c).label ?? columnField(c).label }))
  // Everything the list's search and filters find, page by page.
  const exportAll = async () => {
    const id = sonner.loading(t("exporting", { count: 0 }))
    try {
      const records: Rec[] = []
      const base: Record<string, unknown> = { ...query }
      delete base.page
      delete base.cursor
      let pageNo = 1
      let cursor: string | undefined
      for (;;) {
        const p = await meta.api(api as never).list(
          paged ? { ...base, page: pageNo, per_page: EXPORT_PAGE } : { ...base, limit: EXPORT_PAGE, cursor },
        )
        records.push(...p.items)
        sonner.loading(t("exporting", { count: records.length }), { id })
        if (records.length >= EXPORT_MAX) break
        if (paged ? pageNo >= (p.total_pages ?? 1) : !p.next) break
        pageNo++
        cursor = p.next
      }
      download(fileName(meta.name), toCsv(shown(), records.slice(0, EXPORT_MAX)))
      sonner.success(t("exported", { count: Math.min(records.length, EXPORT_MAX) }), { id })
    } catch (e) {
      sonner.error(describe(e), { id })
    }
  }

  // The keyboard (the page's own list): j and k move, Enter or o opens, e
  // edits, x selects.
  const [active, setActive] = useState(-1)
  useEffect(() => setActive(-1), [JSON.stringify(search)])
  const rowsShown = table.getRowModel().rows
  const move = (by: number) => {
    const next = Math.max(0, Math.min(rowsShown.length - 1, active + by))
    setActive(next)
    document.querySelector(`[data-row-index="${next}"]`)?.scrollIntoView({ block: "nearest" })
  }
  const at = () => rowsShown[active]
  useKeys(
    {
      j: () => move(1),
      ArrowDown: () => move(1),
      k: () => move(-1),
      ArrowUp: () => move(-1),
      Enter: () => at() && navigate({ to: `/${meta.name}/${at()!.original.id}` as never }),
      o: () => at() && navigate({ to: `/${meta.name}/${at()!.original.id}` as never }),
      e: () => at() && (at()!.original.can ?? []).includes("update") && navigate({ to: `/${meta.name}/${at()!.original.id}/edit` as never }),
      x: () => selectable && at()?.toggleSelected(),
    },
    !embedded && rowsShown.length > 0,
  )

  const [density, setDensity] = useDensity()
  const [filtersOpen, setFiltersOpen] = useState(false)
  // Saved filters: the lists of a page, not the ones on a record's page.
  const saved = useViews(meta)
  const saveButton = !embedded && <SaveFilterButton views={saved.views} search={search} onSave={(name) => saved.save(name, search)} />
  const layout = resource.table.filterLayout ?? filterLayout
  const values = search as Record<string, string | undefined>
  const setFilters = (changes: Record<string, string | undefined>) => set({ ...changes, page: undefined, cursor: undefined })

  const searchable = resource.table.search !== false && meta.sorts.includes("relevance")
  const current = search.page ?? 1
  const create = page?.can.includes("create") && (
    <Button asChild size={embedded ? "sm" : "default"} variant={embedded ? "outline" : "default"}>
      <Link to={`/${meta.name}/new` as never} search={(scope ? { [scope.param]: scope.value } : {}) as never}>
        <Plus /> {t("new")}
      </Link>
    </Button>
  )
  const hideable = table.getAllColumns().filter((c) => c.getCanHide())
  const width = table.getVisibleLeafColumns().length
  const exportButton = (
    <Button variant="outline" onClick={exportAll} disabled={!page || page.items.length === 0} size={embedded ? "sm" : "default"}>
      <Download /> {t("export")}
    </Button>
  )
  const importButton = meta.import && page?.can.includes("create") && (
    <Button variant="outline" onClick={() => setImporting(true)} size={embedded ? "sm" : "default"}>
      <Upload /> {t("importAction")}
    </Button>
  )
  return (
    <div className={cn("flex flex-col gap-4", !embedded && "rounded-xl border border-border bg-card p-5")}>
      {embedded ? (
        <div className="flex items-center justify-between gap-2">
          <h2 className="text-lg font-bold tracking-tight">{scope.label ?? meta.label}</h2>
          <div className="flex gap-2">
            {importButton}
            {exportButton}
            {create}
          </div>
        </div>
      ) : (
        <PageHeader
          title={meta.label}
          description={description}
          actions={
            <>
              {meta.trash && (
                <Button variant="outline" onClick={() => navigate({ to: ".", search: { trash: 1 } as never })}>
                  <Trash2 /> {t("trash")}
                  {Boolean(trashCount) && <span className="rounded-full bg-muted px-1.5 text-xs font-semibold tabular-nums">{trashCount}</span>}
                </Button>
              )}
              {importButton}
              {exportButton}
              {create}
            </>
          }
        />
      )}
      <div className="flex flex-wrap items-center gap-2">
        {searchable && (
          <div className="min-w-60 flex-1">
            <SearchBox
              value={search.q ?? ""}
              busy={list.isFetching}
              placeholder={t("searchIn", { name: meta.label.toLocaleLowerCase() })}
              onSearch={(q) => set({ q: q || undefined, page: undefined, cursor: undefined }, true)}
              shortcut={!embedded}
              wide
            />
          </div>
        )}
        {filters.length > 0 &&
          (layout === "bar" ? (
            filters.map((f) => <BarFilter key={f.name} field={f} values={values} onChange={setFilters} />)
          ) : (
            <FilterPanel filters={filters} values={values} onApply={setFilters} layout={layout} open={filtersOpen} onOpenChange={setFiltersOpen} />
          ))}
        {layout === "bar" && filters.some((f) => isActive(f, values)) && (
          <>
            <Button variant="ghost" onClick={() => setFilters(cleared(filters))}>
              <X /> {t("clearFilters")}
            </Button>
            {saveButton}
          </>
        )}
        {!embedded && <SavedFiltersMenu views={saved.views} search={search} onApply={(s) => navigate({ to: ".", search: s as never })} onRemove={saved.remove} />}
        {(hideable.length > 1 || !embedded) && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="icon" aria-label={t("columns")}>
                <Columns3 />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              <DropdownMenuLabel className="text-xs font-normal text-muted-foreground">{t("columns")}</DropdownMenuLabel>
              {hideable.map((c) => (
                <DropdownMenuCheckboxItem
                  key={c.id}
                  checked={c.getIsVisible()}
                  onCheckedChange={(v) => c.toggleVisibility(!!v)}
                  onSelect={(e) => e.preventDefault()}
                >
                  {(c.columnDef.meta as { label?: string } | undefined)?.label ?? c.id}
                </DropdownMenuCheckboxItem>
              ))}
              <DropdownMenuSeparator />
              <DropdownMenuLabel className="text-xs font-normal text-muted-foreground">{t("density")}</DropdownMenuLabel>
              <DropdownMenuRadioGroup value={density} onValueChange={(v) => setDensity(v as Density)}>
                <DropdownMenuRadioItem value="comfortable" onSelect={(e) => e.preventDefault()}>
                  {t("comfortable")}
                </DropdownMenuRadioItem>
                <DropdownMenuRadioItem value="compact" onSelect={(e) => e.preventDefault()}>
                  {t("compact")}
                </DropdownMenuRadioItem>
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
      {layout !== "bar" && (
        <ActiveFilters filters={filters} values={values} onChange={setFilters} onOpen={() => setFiltersOpen(true)}>
          {saveButton}
        </ActiveFilters>
      )}
      {tabsField && (
        <FilterTabs
          field={tabsField}
          value={values[tabsField.name]}
          onChange={(v) => setFilters({ [tabsField.name]: v })}
          count={paged ? (v) => counts[tabValues.indexOf(v)]?.data?.total : undefined}
        />
      )}
      {selected.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg bg-primary/10 px-4 py-2.5 text-sm animate-in fade-in-0 slide-in-from-top-1">
          <span className="font-medium">{t("selected", { count: selected.length })}</span>
          <Button variant="ghost" size="sm" onClick={() => setRowSelection({})}>
            <X /> {t("clearSelection")}
          </Button>
          <div className="ml-auto flex flex-wrap gap-2">
            <Button size="sm" variant="outline" onClick={() => download(fileName(meta.name), toCsv(shown(), selected))}>
              <Download /> {t("export")}
            </Button>
            {bulkActions.map((a) => {
              const records = selected.filter((r) => allowed(a, r))
              return (
                <Button
                  key={a.label}
                  size="sm"
                  variant={a.destructive ? "destructive-outline" : "outline"}
                  disabled={records.length === 0}
                  onClick={() => runBulk(a.label, records, (r) => applyAction(meta, a, r), a.confirm, a.destructive)}
                >
                  {a.icon && <a.icon />} {a.label}
                </Button>
              )
            })}
            {selected.some((r) => (r.can ?? []).includes("delete")) && (
              <Button
                size="sm"
                variant="destructive-outline"
                onClick={() => {
                  const records = selected.filter((r) => (r.can ?? []).includes("delete"))
                  runBulk(
                    meta.trash ? t("moveToTrash") : t("delete"),
                    records,
                    remove,
                    meta.trash ? t("trashManyQ", { count: records.length }) : t("confirmDeleteMany", { count: records.length }),
                    !meta.trash,
                  )
                }}
              >
                <Trash2 /> {t("delete")}
              </Button>
            )}
          </div>
        </div>
      )}
      {list.isError && page && <RefreshError error={list.error} onRetry={() => list.refetch()} />}
      <div className="relative overflow-x-auto">
        <LoadingBar active={list.isFetching && !list.isPending} />
        <SearchContext value={search.q ?? ""}>
        <Table
          className={cn(
            "transition-opacity",
            list.isFetching && !list.isPending && "opacity-60",
            density === "compact" && "[&_td]:py-1 [&_th]:h-8",
          )}
        >
          <TableHeader>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id}>
                {group.headers.map((header) => (
                  <TableHead key={header.id} className={header.column.id === "select" ? "w-10" : header.column.id === "actions" ? "w-12" : undefined}>
                    {header.isPlaceholder ? null : <FlexRender header={header} />}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {list.isPending && <TableSkeleton columns={width} />}
            {table.getRowModel().rows.map((row, i) => (
              <TableRow
                key={row.id}
                data-row-index={i}
                data-state={row.getIsSelected() ? "selected" : undefined}
                aria-current={i === active || undefined}
                className={cn("cursor-pointer", i === active && "bg-muted/60 shadow-[inset_3px_0_0_var(--primary)]")}
                onClick={() => navigate({ to: `/${meta.name}/${row.original.id}` as never })}
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id} className={cn(cell.column.id === titleColumn && "font-bold text-foreground")}>
                    <FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
        </SearchContext>
        {list.isError && !page && <ErrorState className="border-t" error={list.error} onRetry={() => list.refetch()} />}
        {page?.items.length === 0 &&
          (filtering ? (
            <NoResultsState className="border-t" query={search.q} onClear={clearAll} />
          ) : (
            <EmptyState
              className="border-t"
              action={
                page.can.includes("create") && (
                  <Button asChild>
                    <Link to={`/${meta.name}/new` as never}>
                      <Plus /> {t("creating", { name: meta.singular })}
                    </Link>
                  </Button>
                )
              }
            />
          ))}
      </div>
      {paged && page && page.items.length > 0 && (
        <div className="flex flex-wrap items-center justify-between gap-3 text-sm">
          {/* Where the page is among all: 11–20 of 57. */}
          {page.total !== undefined && (
            <p className="text-muted-foreground">
              {t("showing", {
                from: (current - 1) * (Number(search.per) || PER_PAGE) + 1,
                to: (current - 1) * (Number(search.per) || PER_PAGE) + page.items.length,
                total: page.total,
              })}
            </p>
          )}
          <div className="ml-auto flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-1">
            <Button variant="ghost" size="icon-sm" disabled={current <= 1} onClick={() => set({ page: current - 1 })} aria-label={t("previous")}>
              <ChevronLeft />
            </Button>
            {pageNumbers(current, page.total_pages ?? 1).map((n, i) =>
              n === 0 ? (
                <span key={`gap-${i}`} className="px-1 text-muted-foreground">
                  …
                </span>
              ) : (
                <Button
                  key={n}
                  variant="ghost"
                  size="icon-sm"
                  className={cn(n === current && "bg-primary/10 text-primary hover:bg-primary/15 hover:text-primary")}
                  aria-current={n === current ? "page" : undefined}
                  onClick={() => set({ page: n })}
                >
                  {n}
                </Button>
              ),
            )}
            <Button
              variant="ghost"
              size="icon-sm"
              disabled={current >= (page.total_pages ?? 1)}
              onClick={() => set({ page: current + 1 })}
              aria-label={t("next")}
            >
              <ChevronRight />
            </Button>
          </div>
          <Select value={String(Number(search.per) || PER_PAGE)} onValueChange={(v) => set({ per: Number(v) === PER_PAGE ? undefined : v, page: undefined })}>
            <SelectTrigger size="sm" className="w-auto">
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper" align="end">
              {PAGE_SIZES.map((n) => (
                <SelectItem key={n} value={String(n)}>
                  {t("perPage", { count: n })}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          </div>
        </div>
      )}
      {!paged && (search.cursor || page?.next) && (
        <div className="flex items-center justify-end gap-2">
          <Button variant="outline" size="sm" disabled={!search.cursor} onClick={() => (embedded ? set({ cursor: undefined }) : history.back())}>
            <ChevronLeft /> {t("previous")}
          </Button>
          <Button variant="outline" size="sm" disabled={!page?.next} onClick={() => set({ cursor: page?.next })}>
            {t("next")} <ChevronRight />
          </Button>
        </div>
      )}
      {meta.import && <ImportDialog meta={meta} open={importing} onOpenChange={setImporting} />}
      {actionDialog}
    </div>
  )
}
